package com.jinloes.practice;
final class Workload { static final String UNIT="search"; static final int[] SIZES={4096,8192,16384,32768,65536}; private Workload(){} record State(Solution.TreeNode root,int[] keys){} static Object prepare(int size){ int[] keys=new int[size]; for(int i=0;i<size;i++)keys[i]=i; return new State(build(0,size*2), keys); } static void run(Object state){ State s=(State)state; for(int key:s.keys){ Integer v=Solution.firstGreater(s.root,key); if(v==null||v<=key) throw new IllegalStateException(); } } static int units(int size){ return size; } static Solution.TreeNode build(int lo,int hi){ if(lo>=hi)return null; int mid=(lo+hi)/2; return new Solution.TreeNode(mid, build(lo,mid), build(mid+1,hi)); } }
